alter table public.idea_reviews add column if not exists idea_version integer;
create or replace function app_private.idea_review_basis_version(p_idea_id uuid) returns integer language sql stable security definer set search_path='' as $$ with i as (select id,version from public.ideas where id=p_idea_id),d as (select idea_version from public.idea_decisions where idea_id=p_idea_id order by decided_at desc,id desc limit 1) select case when d.idea_version is not null and i.version=d.idea_version+1 then d.idea_version else i.version end from i left join d on true $$;
update public.idea_reviews r set idea_version=app_private.idea_review_basis_version(r.idea_id) where r.idea_version is null;
create or replace function public.submit_idea_review_v1(p_idea_id uuid,p_vote text,p_comment text default ''::text) returns void language plpgsql security definer set search_path='' as $$ declare v_basis integer; begin if not app_private.can_access_idea(p_idea_id) then raise exception 'FORBIDDEN'; end if; if p_vote not in ('approve','deepen','park','reject') then raise exception 'INVALID_IDEA_REVIEW'; end if; v_basis:=app_private.idea_review_basis_version(p_idea_id); if v_basis is null then raise exception 'IDEA_NOT_FOUND'; end if; insert into public.idea_reviews(idea_id,user_id,vote,comment,idea_version) values(p_idea_id,auth.uid(),p_vote,coalesce(p_comment,''),v_basis) on conflict(idea_id,user_id) do update set vote=excluded.vote,comment=excluded.comment,idea_version=excluded.idea_version,updated_at=now(); update public.ideas set status=case when status in ('ready_for_review','exploring') then 'in_review' else status end,readiness='decision' where id=p_idea_id; end $$;
create or replace function public.submit_idea_team_feedback_v3(p_idea_id uuid,p_stance text,p_comment text default null::text) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid(); v_basis integer; begin if v_user is null or not app_private.can_access_idea(p_idea_id) then raise exception 'FORBIDDEN'; end if; if p_stance not in ('approve','deepen','park','reject') then raise exception 'INVALID_STANCE'; end if; v_basis:=app_private.idea_review_basis_version(p_idea_id); if v_basis is null then raise exception 'IDEA_NOT_FOUND'; end if; insert into public.idea_team_feedback(idea_id,user_id,stance,comment) values(p_idea_id,v_user,p_stance,coalesce(p_comment,'')) on conflict(idea_id,user_id) do update set stance=excluded.stance,comment=excluded.comment,updated_at=now(); insert into public.idea_reviews(idea_id,user_id,vote,comment,idea_version) values(p_idea_id,v_user,p_stance,coalesce(p_comment,''),v_basis) on conflict(idea_id,user_id) do update set vote=excluded.vote,comment=excluded.comment,idea_version=excluded.idea_version,updated_at=now(); update public.ideas set status=case when status in ('ready_for_review','exploring') then 'in_review' else status end,readiness='decision' where id=p_idea_id; return jsonb_build_object('idea_id',p_idea_id,'stance',p_stance,'idea_version',v_basis); end $$;
create or replace function public.get_idea_decision_brief_v5(p_idea_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_idea public.ideas; v_decision public.idea_decisions; v_basis integer; v_total int:=0; v_approve int:=0; v_deepen int:=0; v_park int:=0; v_reject int:=0; v_stale int:=0; v_open_questions int:=0; v_open_risks int:=0; v_evidence int:=0; v_can_manage boolean:=false; v_fresh_approval boolean:=false; begin if not app_private.can_access_idea(p_idea_id) then raise exception 'FORBIDDEN'; end if; select * into v_idea from public.ideas where id=p_idea_id; if v_idea.id is null then raise exception 'IDEA_NOT_FOUND'; end if; v_can_manage:=app_private.can_manage_idea(p_idea_id); v_basis:=app_private.idea_review_basis_version(p_idea_id); select * into v_decision from public.idea_decisions where idea_id=p_idea_id order by decided_at desc,id desc limit 1; v_fresh_approval:=v_decision.id is not null and v_decision.outcome='approved' and v_decision.idea_version is not null and v_decision.idea_version=v_idea.version-1; select count(*) filter(where idea_version=v_basis),count(*) filter(where idea_version=v_basis and vote='approve'),count(*) filter(where idea_version=v_basis and vote='deepen'),count(*) filter(where idea_version=v_basis and vote='park'),count(*) filter(where idea_version=v_basis and vote='reject'),count(*) filter(where idea_version is distinct from v_basis) into v_total,v_approve,v_deepen,v_park,v_reject,v_stale from public.idea_reviews where idea_id=p_idea_id; select count(*) filter(where kind='question' and state not in ('resolved','drop')),count(*) filter(where kind='risk' and state not in ('resolved','drop')),count(*) filter(where kind in ('reference','evidence') and state<>'drop') into v_open_questions,v_open_risks,v_evidence from public.idea_items where idea_id=p_idea_id; return jsonb_build_object('idea_id',p_idea_id,'status',v_idea.status,'version',v_idea.version,'review_basis_version',v_basis,'can_manage',v_can_manage,'core_complete',(nullif(btrim(v_idea.problem),'') is not null and nullif(btrim(v_idea.audience),'') is not null and nullif(btrim(v_idea.proposal),'') is not null),'open_questions',v_open_questions,'open_risks',v_open_risks,'evidence_count',v_evidence,'feedback',jsonb_build_object('total',v_total,'approve',v_approve,'deepen',v_deepen,'park',v_park,'reject',v_reject,'stale',v_stale),'approval_fresh',v_fresh_approval,'conversion_allowed',(v_can_manage and v_idea.status='approved' and v_fresh_approval and v_idea.converted_project_id is null),'converted_project_id',v_idea.converted_project_id); end $$;
